/** Экран 1. Создание профиля игры. */
import { useStore } from '../store';
import { ProjectImport } from '../components/ProjectImport';
import { Card, Field, NumberInput, Select, Toggle } from '../components/ui';

/**
 * Скоуп проекта — ПК и macOS. Остальные значения enum Platform живут только
 * для честности данных (примеры реальных мультиплатформенных игр) и в API,
 * но в анкету не предлагаются.
 */
const QUESTIONNAIRE_PLATFORMS = ['pc_windows', 'pc_linux', 'macos'];

const RESOLUTIONS = [
  { value: '720p', label: '720p' },
  { value: '1080p', label: '1080p (Full HD)' },
  { value: '1440p', label: '1440p (2K)' },
  { value: '2160p', label: '2160p (4K)' },
];

const QUALITY = [
  { value: 'low', label: 'низкое' },
  { value: 'medium', label: 'среднее' },
  { value: 'high', label: 'высокое' },
  { value: 'ultra', label: 'ультра' },
];

export function ProfileScreen() {
  const { profile, updateProfile, catalog } = useStore();
  const { enums, engines, functions } = catalog;

  if (!enums) return null;

  const selectedEngine = engines.find((engine) => engine.code === profile.engine);

  return (
    <>
      <ProjectImport />
      <Card
        title="Общие сведения о проекте"
        hint="Опишите будущую игру: формат, структуру мира, технологии и целевые показатели."
      >
        <div className="grid grid-2">
          <Field label="Название проекта">
            <input
              type="text"
              value={profile.name}
              onChange={(e) => updateProfile({ name: e.target.value })}
            />
          </Field>

          <Field label="Формат изображения">
            <Select
              value={profile.format}
              options={enums.formats}
              onChange={(value) => updateProfile({ format: value })}
            />
          </Field>

          <Field label="Структура игрового мира">
            <Select
              value={profile.world_type}
              options={enums.world_types}
              onChange={(value) => updateProfile({ world_type: value })}
            />
          </Field>

          <Field label="Масштаб мира">
            <Select
              value={profile.scale}
              options={enums.scales}
              onChange={(value) => updateProfile({ scale: value })}
            />
          </Field>

          <Field label="Игровой движок">
            <Select
              value={profile.engine}
              options={engines.map((engine) => ({ value: engine.code, label: engine.name }))}
              onChange={(value) => updateProfile({ engine: value, engine_version: null })}
            />
          </Field>

          <Field
            label="Версия движка"
            hint={selectedEngine ? `Доступные версии: ${selectedEngine.versions.join(', ')}` : undefined}
          >
            <Select
              value={profile.engine_version ?? ''}
              options={(selectedEngine?.versions ?? []).map((version) => ({
                value: version,
                label: version,
              }))}
              placeholder="версия не указана"
              onChange={(value) => updateProfile({ engine_version: value || null })}
            />
          </Field>
        </div>

        <div className="divider" />
        <Field
          label="Целевые платформы"
          hint="Решения, не поддерживаемые хотя бы одной платформой, будут исключены из рекомендаций."
        >
          <div className="chip-row">
            {enums.platforms
              .filter((platform) => QUESTIONNAIRE_PLATFORMS.includes(platform.value))
              .map((platform) => {
                const active = profile.platforms.includes(platform.value);
                return (
                  <button
                    key={platform.value}
                    className={`chip ${active ? 'selected' : ''}`}
                    onClick={() =>
                      updateProfile({
                        platforms: active
                          ? profile.platforms.filter((p) => p !== platform.value)
                          : [...profile.platforms, platform.value],
                      })
                    }
                  >
                    {platform.label}
                  </button>
                );
              })}
          </div>
        </Field>
      </Card>

      <Card title="Целевые показатели качества и производительности">
        <div className="grid grid-4">
          <Field label="Целевое разрешение">
            <Select
              value={profile.target_resolution}
              options={RESOLUTIONS}
              onChange={(value) => updateProfile({ target_resolution: value })}
            />
          </Field>
          <Field label="Целевое качество">
            <Select
              value={profile.target_quality}
              options={QUALITY}
              onChange={(value) => updateProfile({ target_quality: value })}
            />
          </Field>
          <Field label="Целевой FPS" hint="Допустимый диапазон 15–480">
            <NumberInput
              value={profile.target_fps}
              min={15}
              max={480}
              onChange={(value) => updateProfile({ target_fps: value ?? 60 })}
            />
          </Field>
          <Field
            label="Приоритет"
            hint="Определяет веса критериев при ранжировании решений."
          >
            <Select
              value={profile.priority}
              options={enums.priorities}
              onChange={(value) => updateProfile({ priority: value })}
            />
          </Field>
        </div>
      </Card>

      <Card
        title="Обязательные ограничения"
        hint="Заполняйте только те ограничения, которые действительно заданы: они работают как жёсткий фильтр."
      >
        <div className="grid grid-4">
          <Field label="Предел RAM, ГБ">
            <NumberInput
              value={profile.ram_limit_gb ?? null}
              min={1}
              placeholder="не задан"
              onChange={(value) => updateProfile({ ram_limit_gb: value })}
            />
          </Field>
          <Field label="Предел VRAM, ГБ">
            <NumberInput
              value={profile.vram_limit_gb ?? null}
              min={1}
              placeholder="не задан"
              onChange={(value) => updateProfile({ vram_limit_gb: value })}
            />
          </Field>
          <Field label="Предел размера игры, ГБ">
            <NumberInput
              value={profile.size_limit_gb ?? null}
              min={1}
              placeholder="не задан"
              onChange={(value) => updateProfile({ size_limit_gb: value })}
            />
          </Field>
          <Field label="Срок, недель">
            <NumberInput
              value={profile.deadline_weeks ?? null}
              min={1}
              placeholder="не задан"
              onChange={(value) => updateProfile({ deadline_weeks: value })}
            />
          </Field>
        </div>

        <div className="divider" />
        <Field
          label="Допустимая сложность внедрения"
          hint={`Решения со сложностью выше ${profile.complexity_tolerance ?? 5} из 5 будут исключены.`}
        >
          <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
            <input
              type="range"
              min={1}
              max={5}
              value={profile.complexity_tolerance ?? 5}
              onChange={(e) => {
                const value = Number(e.target.value);
                updateProfile({ complexity_tolerance: value === 5 ? null : value });
              }}
            />
            <span className="mono nowrap">
              {profile.complexity_tolerance ?? 5} / 5
              {profile.complexity_tolerance === null && <span className="faint"> — без ограничения</span>}
            </span>
          </div>
        </Field>
      </Card>

      <Card
        title="Сетевой режим"
        hint="Влияет на оценку сетевой нагрузки и на подбор решений репликации."
      >
        <div style={{ display: 'flex', gap: 10, alignItems: 'flex-end', flexWrap: 'wrap' }}>
          <Toggle
            checked={profile.multiplayer}
            onChange={(value) => updateProfile({ multiplayer: value, player_count: value ? Math.max(2, profile.player_count) : 1 })}
            label="Мультиплеер предусмотрен"
          />
          {profile.multiplayer && (
            <div style={{ minWidth: 180 }}>
              <Field label="Игроков в сессии">
                <NumberInput
                  value={profile.player_count}
                  min={2}
                  onChange={(value) => updateProfile({ player_count: Math.max(1, value ?? 1) })}
                />
              </Field>
            </div>
          )}
        </div>
      </Card>

      <Card title="Масштаб сцены" hint="Если точные числа неизвестны, используйте качественные уровни.">
        <div className="grid grid-2">
          <Field label="Количество объектов">
            <Select
              value={profile.object_count_level}
              options={enums.levels}
              onChange={(value) => updateProfile({ object_count_level: value })}
            />
          </Field>
          <Field label="Количество NPC">
            <Select
              value={profile.npc_count_level}
              options={enums.levels}
              onChange={(value) => updateProfile({ npc_count_level: value })}
            />
          </Field>
          <Field label="Точное число объектов" hint="Необязательно">
            <NumberInput
              value={profile.object_count ?? null}
              min={0}
              placeholder="не задано"
              onChange={(value) => updateProfile({ object_count: value })}
            />
          </Field>
          <Field label="Точное число NPC" hint="Необязательно">
            <NumberInput
              value={profile.npc_count ?? null}
              min={0}
              placeholder="не задано"
              onChange={(value) => updateProfile({ npc_count: value })}
            />
          </Field>
        </div>
        <p className="xsmall faint" style={{ marginTop: 10 }}>
          Доступно игровых функций в базе знаний: {functions.length}.
        </p>
      </Card>
    </>
  );
}

"""Перечисления предметной области.

Хранятся в БД как строки, чтобы схема одинаково работала в SQLite и PostgreSQL.
"""
from __future__ import annotations

from enum import Enum


class Status(str, Enum):
    """Жизненный цикл записи базы знаний."""

    DRAFT = "draft"           # черновик
    REVIEWED = "reviewed"     # проверено
    PUBLISHED = "published"   # опубликовано

    @property
    def label(self) -> str:
        return {
            "draft": "черновик",
            "reviewed": "проверено",
            "published": "опубликовано",
        }[self.value]


class SolutionLevel(str, Enum):
    """Уровень решения."""

    ARCHITECTURE = "architecture"    # архитектура
    PRODUCTION = "production"        # производственный процесс
    ALGORITHM = "algorithm"          # алгоритм
    SETTING = "setting"              # настройка

    @property
    def label(self) -> str:
        return {
            "architecture": "архитектура",
            "production": "производственный процесс",
            "algorithm": "алгоритм",
            "setting": "настройка",
        }[self.value]


class DevStage(str, Enum):
    """Стадия разработки проекта."""

    CONCEPT = "concept"                  # концепт
    PREPRODUCTION = "preproduction"      # предпроизводство
    PROTOTYPE = "prototype"              # прототип
    PRODUCTION = "production"            # производство контента
    ALPHA = "alpha"
    BETA = "beta"
    RELEASE = "release"                  # релиз
    POST_RELEASE = "post_release"        # поддержка после релиза

    @property
    def label(self) -> str:
        return {
            "concept": "концепт",
            "preproduction": "предпроизводство",
            "prototype": "прототип",
            "production": "производство контента",
            "alpha": "альфа",
            "beta": "бета",
            "release": "релиз",
            "post_release": "поддержка после релиза",
        }[self.value]

    @property
    def order(self) -> int:
        """Порядковый номер стадии: чем больше, тем позже внедрять изменения дороже."""
        return {
            "concept": 0,
            "preproduction": 1,
            "prototype": 2,
            "production": 3,
            "alpha": 4,
            "beta": 5,
            "release": 6,
            "post_release": 7,
        }[self.value]


class LateCost(str, Enum):
    """Стоимость внедрения после рекомендованной стадии."""

    LOW = "low"          # низкая
    MEDIUM = "medium"    # средняя
    HIGH = "high"        # высокая
    CRITICAL = "critical"  # критическая

    @property
    def label(self) -> str:
        return {"low": "низкая", "medium": "средняя", "high": "высокая", "critical": "критическая"}[self.value]

    @property
    def weight(self) -> float:
        return {"low": 0.0, "medium": 0.35, "high": 0.7, "critical": 1.0}[self.value]


class CalcMode(str, Enum):
    """Способ расчёта."""

    REALTIME = "realtime"        # в реальном времени
    PRECOMPUTED = "precomputed"  # предварительный
    HYBRID = "hybrid"            # гибридный

    @property
    def label(self) -> str:
        return {"realtime": "real-time", "precomputed": "предварительный", "hybrid": "гибридный"}[self.value]


class RelationType(str, Enum):
    """Тип связи общего метода с инструментом движка."""

    DIRECT = "direct"                # прямая реализация
    PARTIAL = "partial"              # частичный аналог
    ALTERNATIVE = "alternative"      # альтернативный подход
    COMPLEMENT = "complement"        # дополнение
    AUTOMATION = "automation"        # автоматизация
    DIAGNOSTIC = "diagnostic"        # диагностический инструмент
    LIMITED = "limited"              # ограниченное применение
    MISSING = "missing"              # отсутствие встроенного аналога

    @property
    def label(self) -> str:
        return {
            "direct": "прямая реализация",
            "partial": "частичный аналог",
            "alternative": "альтернативный подход",
            "complement": "дополнение",
            "automation": "автоматизация",
            "diagnostic": "диагностический инструмент",
            "limited": "ограниченное применение",
            "missing": "отсутствие встроенного аналога",
        }[self.value]


class ConflictType(str, Enum):
    CONFLICT = "conflict"      # конфликт
    DEPENDENCY = "dependency"  # зависимость
    SYNERGY = "synergy"        # усиление

    @property
    def label(self) -> str:
        return {"conflict": "конфликт", "dependency": "зависимость", "synergy": "усиление"}[self.value]


class MethodKind(str, Enum):
    IMPLEMENTATION = "implementation"  # вариант реализации функции
    OPTIMIZATION = "optimization"      # общий метод оптимизации

    @property
    def label(self) -> str:
        return {"implementation": "вариант реализации", "optimization": "метод оптимизации"}[self.value]


class GameFormat(str, Enum):
    FMT_2D = "2D"
    FMT_25D = "2.5D"
    FMT_3D = "3D"

    @property
